// Package cgo checks that the files of packages which use cgo are not skipped
// as generated: cmd/cgo adds "Code generated by cmd/cgo; DO NOT EDIT." to them.
package cgo

/*
#include <stdlib.h>
*/
import "C"

import (
	"strconv"
	"unsafe"

	"github.com/pkg/errors"
)

func free(cs *C.char) {
	C.free(unsafe.Pointer(cs))
}

func parse(s string) error {
	cs := C.CString(s)
	defer free(cs)

	_, err := strconv.Atoi(s)
	if err != nil {
		return errors.Wrap(err, "strconv.Atoi")
	}

	_, err = strconv.Atoi(s)
	if err != nil {
		return errors.Wrap(err, "ParseInt") // want "message in errors.Wrap does not match function or method name"
	}

	return nil
}
